def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: The nanoseconds since epoch.
    :param tz: The time zone as an offset from UTC (default: None).
    :return: A `Time` or `LocalTime` object, depending on the value of `tz`.
    """
    # Parse the nanoseconds since epoch
    try:
        nanoseconds = int(nanoseconds)
