def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if not varargs:
        raise ValueError("Must provide at least one argument")

    if color and not _is_terminal_interactive():
        raise ValueError("Cannot enable color when running non-interactively")

    partitions = _partition_varargs(varargs, target_concurrency)
    if not partitions:
        raise ValueError("Cannot partition varargs into at least one group")

    results = []
    for i, partition in enumerate(partitions):
        if color:
            partition = _colorize_partition(partition)
        cmd_str = " ".join(cmd + partition)
        try:
            result = subprocess.run(cmd_str, shell=True, capture_output=True, encoding="utf-8")
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Command failed with exit code {e.returncode}: {e.stderr}")
        results.append((i, partition, result.returncode, result.stdout))

    return tuple(results)

