def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd or len(cmd) == 0:
        raise ValueError("Empty command provided")

    clean_cmd = []
    for arg in cmd:
        if not arg.strip():
            continue
        arg = arg.replace("\\", "/")
        if arg.startswith("//"):
            arg = arg[2:]
        clean_cmd.append(arg)

    if not clean_cmd:
        raise ValueError("Invalid command format")

    return tuple(clean_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    # Check if the command is a tuple
    if not isinstance(cmd, tuple):
        raise TypeError("Command must be a tuple of strings")

    # Check if the command is a valid shell command
    if not check_shell_command(cmd[0]):
        raise ValueError(f"Invalid shell command: {cmd[0]}")

    # Normalize the command
    normalized_cmd = [cmd[0]]
    for arg in cmd[1:]:
        # Check if the argument is a valid command argument
        if not check_command_argument(arg):
            raise ValueError(f"Invalid command argument: {arg}")

        # Normalize the argument
        normalized_cmd.append(arg)

    # Return the normalized command
    return tuple(normalized_cmd)

def check_shell_command(cmd: str) -> bool:
    """Checks if the given command is a valid shell command"""
    # Check if the command is a valid path
    if not os.path.exists(cmd):
        return False

    # Check if the command is a directory
    if os.path.isdir(cmd):
        return False

    # Check if the command is a file with executable permissions
    if not os.access(cmd, os.X_OK):
        return False

    return True

def check_command_argument(arg: str) -> bool:
    """Checks if the given argument is a valid command argument"""
    # Check if the argument is a valid path
    if not os.path.exists(arg):
        return False

    # Check if the argument is a directory
    if os.path.isdir(arg):
        return False

    return True

