    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        def _wrapper(*args):
            if args in cache:
                cache[args] += 1
            else:
                cache[args] = 1
            if len(cache) > maxsize:
                cache.pop(min(cache, key=cache.get))
            return func(*args)
        return _wrapper
    return wrapper

