def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Args:
        cache (dict or str): A dictionary or the name of a cache to use.
        key (str): The key to use for the cache.
        lock (threading.Lock or bool): A lock to use for multithreading,
            or True to create a new one, or False to not lock.

    Returns:
        Callable: A memoizing callable that wraps the original function.

    Raises:
        TypeError: If cache is not a dict or a callable, or if key is not
            a string, or if lock is not a threading.Lock or a bool.
        ValueError: If cache is not a valid cache name (e.g. not a string
            or not a valid attribute).
    """
    def decorator(func):
        if not callable(func):
            raise TypeError("func must be callable")

        func_module = getattr(func, "__module__", None)
        func_name = getattr(func, "__qualname__", func.__name__)

        if isinstance(cache, str):
            try:
                cache_obj = getattr(sys.modules[func_module], cache)
            except AttributeError:
                raise ValueError(f"unknown cache: {cache}")

            if not isinstance(cache_obj, dict):
                raise TypeError(f"cache must be a dict, got {type(cache_obj)}")

            cache = dict

        if not isinstance(key, str):
            raise TypeError(f"key must be a str, got {type(key)}")

        if lock is not None and not isinstance(lock, threading.Lock):
            raise TypeError(f"lock must be a threading.Lock or None, got {type(lock)}")

        def wrapper(*args, **kwargs):
            if lock is not None:
                with lock:
                    return cache[key](*args, **kwargs)
            else:
                return cache[key](*args, **kwargs)

        wrapper.__name__ = func_name
        wrapper.__qualname__ = func.__qualname__
        wrapper.__module__ = func_module
        wrapper.__doc__ = func.__doc__

        return wrapper

    return decorator

