def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        # check if bins and edges are of the correct format
        if not (isinstance(bins, list) and isinstance(edges, list)):
            raise TypeError("bins and edges must be lists")
        if not (len(bins) == len(edges) - 1):
            raise ValueError("length of bins and edges must satisfy len(bins) == len(edges) - 1")

        # compute the integral using the trapezoidal rule
        area = 0
        for i in range(len(bins)):
            area += (edges[i + 1] - edges[i]) * (bins[i] + bins[i + 1]) / 2
        return area
    except (TypeError, ValueError) as e:
        # raise a more informative error message
        raise ValueError("invalid input: {}".format(e)) from e

