       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("d1 and d2 must be dictionaries")
    if level == 0:
        return d1
    diff = {}
    for k, v in d1.items():
        if k not in d2:
            diff[k] = v
        else:
            if isinstance(v, dict) and isinstance(d2[k], dict):
                diff[k] = difference(v, d2[k], level-1)
            elif v != d2[k]:
                diff[k] = v
    return diff

