def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    # Step 1: Initialize the regular expressions
    name_regex = r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$"
    namespace_regex = r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$"

    # Step 2: Check if the regular expressions are already compiled
    if re.compile(name_regex, re.IGNORECASE):
        return re.compile(name_regex, re.IGNORECASE)
    elif re.compile(namespace_regex, re.IGNORECASE):
        return re.compile(namespace_regex, re.IGNORECASE)

    # Step 3: Compile the regular expressions if they are not already compiled
    name_regex = re.compile(name_regex, re.IGNORECASE)
    namespace_regex = re.compile(namespace_regex, re.IGNORECASE)

    return (name_regex, namespace_regex)

