def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Step 1: Generate the default observer schema for each Kubernetes resource present in `spec.manifest`
    # Step 2: Check if a custom observer schema has been specified for each resource
    # Step 3: If a custom observer schema has not been specified, use the default observer schema
    # Step 4: If a custom observer schema has been specified, use the custom observer schema

    default_observer_schema = {}
    custom_observer_schema = {}

    # Step 1: Generate the default observer schema for each Kubernetes resource present in `spec.manifest`
    for manifest in app.spec.manifest:
        resource_name = manifest.metadata.name
        resource_namespace = manifest.metadata.namespace
        resource_type = manifest.kind

        default_observer_schema[resource_name] = {
            "name": resource_name,
            "kind": resource_type,
            "namespace": resource_namespace,
            "apiVersion": manifest.apiVersion
        }

    # Step 2: Check if a custom observer schema has been specified for each resource
    custom_observer_schema = {
        resource_name: {
            "name": resource_name,
            "kind": resource_type,
            "namespace": resource_namespace,
            "apiVersion": manifest.apiVersion
        }
        for manifest in app.spec.manifest
        for resource_name, resource_type in app.spec.custom_observer_schema
    }

    # Step 3: If a custom observer schema has not been specified, use the default observer schema
    for resource_name in default_observer_schema:
        if resource_name not in custom_observer_schema:
            custom_observer_schema[resource_name] = default_observer_schema[resource_name]

    # Step 4: If a custom observer schema has been specified, use the custom observer schema
    for resource_name in custom_observer_schema:
        custom_observer_schema[resource_name] = app.spec.custom_observer_schema[resource_name]

    return custom_observer_schema

