def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: The formatted SQL query and the converted out-style parameters.
    :rtype: tuple
    """
    # Check if the input parameters are valid
    if not isinstance(sql, (str, bytes)):
        raise TypeError("The first argument must be of type str or bytes.")
    if not isinstance(params, (dict, list)):
        raise TypeError("The second argument must be of type dict or list.")

    # Check if the parameters are in the correct format
    if isinstance(params, dict):
        for key, value in params.items():
            if not isinstance(key, (str, int)):
                raise TypeError("The keys of the parameter dict must be of type str or int.")
            if not isinstance(value, Any):
                raise TypeError("The values of the parameter dict must be of type Any.")
    else:
        for value in params:
            if not isinstance(value, Any):
                raise TypeError("The values of the parameter list must be of type Any.")

    # Convert the SQL query to use the out-style parameters
    if self.in_style == "named":
        formatted_sql = self._format_named_style(sql, params)
        formatted_params = {key: value for key, value in params.items() if value is not None}
    elif self.in_style == "ordinal":
        formatted_sql = self._format_ordinal_style(sql, params)
        formatted_params = [value for value in params if value is not None]
    else:
        raise ValueError("Invalid parameter style: '{}'".format(self.in_style))

    return formatted_sql, formatted_params
