def formatmany(sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of the
	in-style parameters.

	*sql* (:class:`str` or :class:`bytes`) is the SQL query.

	*many_params* (:class:`~collections.abc.Iterable`) contains each set
	of in-style parameters (*params*).

	-	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
		*params* must be a :class:`~collections.abc.Sequence`.

	Returns a :class:`tuple` containing:

	-	The formatted SQL query (:class:`str` or :class:`bytes`).

	-	A :class:`list` containing each set of converted out-style
		parameters (:class:`dict` or :class:`list`).
	"""
	formatted_sql = sql
	out_style_parameters = many_params

	if isinstance(many_params, Iterable[Dict[Union[str, int], Any]]):
		out_style_parameters = list(many_params)
		for params in out_style_parameters:
			formatted_sql = _format(formatted_sql, params)
	elif isinstance(many_params, Iterable[Sequence[Any]]):
		out_style_parameters = list(many_params)
		for params in out_style_parameters:
			formatted_sql = _format(formatted_sql, params)
	else:
		raise ValueError("many_params must be an Iterable of type Dict[Union[str, int], Any] or Sequence[Any]")

	return formatted_sql, out_style_parameters

def _format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], List[Any]]]:
	if isinstance(params, Mapping):
		return _format_named(sql, params)
	elif isinstance(params, Sequence):
		return _format_ordinal(sql, params)
	else:
		raise ValueError("params must be of type Mapping or Sequence")

def _format_named(sql: AnyStr, params: Dict[Union[str, int], Any]) -> Tuple[AnyStr, Dict[Union[str, int], Any]]:
	for name, value in params.items():
		sql = sql.replace(":" + name, "?")
	return sql, params

def _format_ordinal(sql: AnyStr, params: Sequence[Any]) -> Tuple[AnyStr, List[Any]]:
	for index, value in enumerate(params):
		sql = sql.replace(":" + str(index), "?")
	return sql, list(params)
