def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    path = Path(path)

    # If 'path' is not a directory, it is not valid
    if not path.is_dir():
        return False

    # If 'path' does not contain the 'inventory.json' file, it is not valid
    if not (path / 'inventory.json').is_file():
        return False

    # If 'path' does not contain any version directories, it is not valid
    if not any(p.is_dir() for p in path.glob('v[0-9][0-9][0-9]')):
        return False

    # If 'path' is valid, check for warnings
    warnings = []

    # If 'path' contains a 'root.json' file, but 'inventory.json' is not in the root, it is a warning
    if (path / 'root.json').is_file() and not (path / 'inventory.json').parent.samefile(path.anchor):
        warnings.append("The 'root.json' file is not in the same directory as the inventory.")

    # If 'path' contains a 'digest' directory, but it is not in the root, it is a warning
    if (path / 'digest').is_dir() and not (path / 'digest').parent.samefile(path.anchor):
        warnings.append("The 'digest' directory is not in the same directory as the inventory.")

    # If 'path' contains a 'extensions' directory, but it is not in the root, it is a warning
    if (path / 'extensions').is_dir() and not (path / 'extensions').parent.samefile(path.anchor):
        warnings.append("The 'extensions' directory is not in the same directory as the inventory.")

    # If there are any warnings, return True (valid) with a warning
    if warnings:
        return True, warnings
    else:
        return True

