    if not fixity or not isinstance(fixity, dict):
        raise ValueError("Fixity block is empty or invalid")

    for filename, fixity_info in fixity.items():
        if filename not in manifest_files:
            raise ValueError(f"File {filename} in fixity block is not present in manifest")

        if not isinstance(fixity_info, dict):
            raise ValueError(f"Fixity information for file {filename} is not a dict")

