def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    try:
        with open(file_path, "r") as f:
            data = f.read()
    except FileNotFoundError:
        raise ValueError(f"File not found: {file_path}")
    except PermissionError:
        raise OSError(f"File is not readable: {file_path}")

    file_name = os.path.basename(file_path)
    file_type = _get_file_type(file_name)
    packages = {"asset": {}, "rendition": {}}

    if file_type == "asset":
        asset_id = _get_asset_id(data, file_name)
        packages["asset"][asset_id] = file_path
    elif file_type == "rendition":
        rendition_id = _get_rendition_id(data, file_name)
        packages["rendition"][rendition_id] = file_path
    else:
        raise ValueError(f"Invalid file type: {file_type}")

    return packages

def _get_asset_id(data, file_name):
    match = re.search(r"<asset xmlns=\"(.*?)s\"", data)
    if match:
        return match.group(1)
    else:
