    # Check that the input datetime is timezone-aware
    if dt.tzinfo is None:
        raise ValueError("Expected timezone-aware datetime object")

    # Check that the input datetime is in a valid timezone
    if dt.tzinfo not in self._tzinfos:
        raise ValueError(f"Invalid timezone: {dt.tzinfo}")

    # Calculate the new datetime in the new timezone
    new_dt = dt.astimezone(self._tzinfos[dt.tzinfo])

    # Determine whether the datetime is ambiguous and in a "fold" state
    if new_dt in self._ambiguous_datetimes:
        new_dt = new_dt.replace(fold=1)

