def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return: Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    if not self._has_relative_attributes():
        raise ValueError("This object has no relative attributes to normalize")

    normalized_attributes = {}
    for attr_name, attr_value in self._get_relative_attributes().items():
        if isinstance(attr_value, float):
