def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Check if the path is a file
        if not os.path.isfile(path):
            return "other: Not a file"

        # Check if the file is a Namaste file
        if not regex.match(r"0=.*", path.basename):
            return "other: not a Namaste file"

        # Check if the Namaste file has the right prefix
        if not NamasteFile(path).check_format():
            return "other: Namaste file has invalid prefix"

        # Check if the Namaste file has an OCFL version
        if "OCFL Version" in NamasteFile(path).namastes:
            return "root"
        else:
            return "object"
    except Exception as e:
        return "other: " + str(e)
