def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    archive_path = Path(archive_path)
    if not archive_path.is_file():
        raise ValueError("archive_path must be a file.")

    if filename is None:
        filename = Path(archive_path).stem
    filename = Path(filename).without_suffix().without_suffix()

    if not tmp_path.is_absolute():
        tmp_path = Path(tmp_path.parent, tmp_path)
    try:
        with TemporaryDirectory(dir=tmp_path) as temp_dir:
            uncompress_archive(archive_path, temp_dir)
            repo_url = Path(temp_dir, filename).as_uri()
    except OSError as e:
        raise ValueError(f"Error uncompressing archive: {e}")
    return repo_url

