import subprocess

def get_git_ignored_files(ignored):
    """
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.
    """
    try:
        result = subprocess.check_output(["git", "status", "--ignored", "--porcelain"])
        lines = result.decode("utf-8").splitlines()
        ignored_files = []
        for line in lines:
            if line.startswith("!! "):
                ignored_files.append(line.split("!! ")[-1].strip())
        return ", ".join(ignored_files)
    except subprocess.CalledProcessError as e:
        raise ValueError("The git command failed with exit code {}".format(e.returncode))

