def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    # Make sure the input parameters are valid
    if not config_filename or not rendered_config:
        raise ValueError("Invalid input parameters")
    if not isinstance(mode, int) or not isinstance(overwrite, bool):
        raise TypeError("Invalid input parameters")
    # Create the target directory if it doesn't exist
    try:
        os.makedirs(os.path.dirname(config_filename), exist_ok=True)
    except OSError as e:
        raise RuntimeError("Failed to create containing directory") from e
    # Check if the file already exists and overwrite is False
    if not overwrite and os.path.isfile(config_filename):
        raise RuntimeError("File already exists and overwriting is not allowed")
    # Write the rendered config to the file
    try:
        with open(config_filename, "w+") as f:
            f.write(rendered_config)
    except OSError as e:
        raise RuntimeError("Failed to write config file") from e
    # Set the file mode
    try:
        os.chmod(config_filename, mode)
    except OSError as e:
