    if not url.strip():
        raise ValueError("Invalid URL")
    if not url.startswith(("http://", "https://")):
        raise ValueError("Invalid protocol")

    # Build NodeInfo .well-known URL
    if not document_path:
        document_path = "/.well-known/nodeinfo"
    nodeinfo_url = urljoin(url, document_path)

    # Fetch NodeInfo document
    try:
        response = requests.get(nodeinfo_url, timeout=5)
        response.raise_for_status()
    except requests.RequestException as exc:
        raise RuntimeError(
            f"Failed to fetch NodeInfo document for {nodeinfo_url}: {exc}"
        ) from exc

    # Parse NodeInfo document
    try:
        nodeinfo_doc = json.loads(response.content)
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"Failed to parse NodeInfo document for {nodeinfo_url}: {exc}"
        ) from exc

