def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    To insert a value for a nested key, all ancestor keys should be given as
    method arguments.

    Example: dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: The dictionary object to insert the nested key value into.
    :param val: The value to insert into the given dictionary.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: The sub keys in the keys chain.
    """
    if not isinstance(dic, dict):
        raise TypeError("'dic' must be a dictionary object")

    if not isinstance(val, str):
        raise TypeError("'val' must be a string object")

    if not isinstance(key, str):
        raise TypeError("'key' must be a string object")

    if not isinstance(keys, tuple):
        raise TypeError("'keys' must be a tuple object")

    if not keys:
        raise ValueError("'keys' tuple must not be empty")

    for key in keys:
        if key not in dic:
            dic[key] = {}

        dic = dic[key]

    dic[keys[-1]] = val

def test_dict_insert():
    dic = {}
    dict_insert(dic, 'val', 'key1.key2'.split('.'))
    assert dic == {'key1': {'key2': 'val'}}

    dic = {}
    dict_insert(dic, 'val', 'key1.key2'.split('.'), 'key3')
    assert dic == {'key1': {'key2': {'key3': 'val'}}}

    dic = {}
    dict_insert(dic, 'val', 'key1.key2'.split('.'), 'key3.key4')
    assert dic == {'key1': {'key2': {'key3': {'key4': 'val'}}}}

    dic = {}
    with pytest.raises(TypeError):
        dict_insert(123, 'val', 'key1.key2'.split('.'))

    with pytest.raises(TypeError):
        dict_insert(dic, 123, 'key1.key2'.split('.'))

    with pytest.raises(TypeError):
        dict_insert(dic, 'val', 123.456)

    with pytest.raises(TypeError):
        dict_insert(dic, 'val', 'key1.key2'.split('.'), 123.456)

    with pytest.raises(ValueError):
        dict_insert(dic, 'val', tuple())

    with pytest.raises(ValueError):
        dict_insert(dic, 'val', 'key1.key2'.split('.'), tuple())

