def get_nested_custom_args(self, args: list) -> tuple[dict, dict]:
    """Split the input arguments into control, nested, and custom Ansible arguments.

    Control arguments are destination-specific and used to override the default
    IR behavior. Nested arguments are used by the Ansible playbooks and will be
    put into the spec yml file. Custom arguments are custom Ansible variables
    used to override the normal nested usage.

    :param args: A list of arguments to be parsed.
    :return: A tuple of two dictionaries: (control_args, nested_args)
    """
    try:
        control_args = {}
        nested_args = {}
        custom_args = {}
        for arg in args:
            if arg.startswith("--") and "=" in arg:
                key, value = arg.split("=", 1)
                key = key[2:]
                if key in self.control_arguments:
                    control_args[key] = value
                elif key in self.nested_arguments:
                    nested_args.setdefault(key, []).append(value)
                else:
                    custom_args[key] = value
            elif arg.startswith("-") and len(arg) > 1:
                key = arg[1:]
                value = "True"
                if key in self.control_arguments:
                    control_args[key] = value
                elif key in self.nested_arguments:
                    nested_args.setdefault(key, []).append(value)
                else:
                    custom_args[key] = value
            else:
                raise ValueError(f"Invalid argument: {arg}")
        return control_args, nested_args, custom_args
    except ValueError as e:
        raise ValueError(f"Invalid arguments: {args}. {e}")

