    if ir_plugin is None:
        raise ValueError("An Infrared Plugin object must be provided.")

    if playbook_path is None:
        raise ValueError("A playbook path must be provided.")

    if not isinstance(playbook_path, str):
        raise ValueError("The playbook path must be a string.")

    if not os.path.isfile(playbook_path):
        raise ValueError("The playbook path must be a valid file.")

    # Step 2: Generate the Ansible command
    command = ["ansible-playbook"]

    if verbose is not None:
        command.append(f"-{verbose}")

    if extra_vars is not None:
        command.append("--extra-vars")
        command.append(json.dumps(extra_vars))

    if ansible_args is not None:
        for key, value in ansible_args.items():
            command.append(key)
            command.append(value)

    command.append(playbook_path)

    # Step 3: Execute the Ansible command
    result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    if result.returncode != 0:
        raise RuntimeError(f"Ansible playbook execution failed with exit code {result.returncode}.")

    return result.stdout.decode("utf-8")

