    if not ir_plugin.exists():
        raise ValueError("Infrared Plugin does not exist")
    if not playbook_path.exists():
        raise ValueError("Playbook does not exist")
    if verbose is not None and not isinstance(verbose, int):
        raise TypeError("Verbose argument must be an int")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("Extra vars argument must be a dict")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("Ansible args argument must be a dict")

    workspace_path = ir_workspace.get_path()
    plugin_path = ir_plugin.get_path()
    playbook_path = os.path.join(workspace_path, playbook_path)
    if extra_vars is not None:
        for key, value in extra_vars.items:
            if isinstance(value, list):
                extra_vars[key] = " ".join(value)
            if isinstance(value, dict):
                extra_vars[key] = "{" + ", ".join(str(k) + ": " + str(v) for k, v in value.items()) + "}"
    ansible_args_list = []
    if verbose is not None:
        ansible_args_list.append("-" + str(verbose) + "vvv")
    if extra_vars is not None:
        ansible_args_list.extend(["-e", extra_vars])
    if ansible_args is not None:
        ansible_args_list.extend(ansible_args.items())

    out = ''
    try:
        result = subprocess.run(
            ['ansible-playbook', playbook_path] + ansible_args_list,
            check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE
        )
        out = result.stdout
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        if e.stderr:
            out = e.stderr
        else:
            out = e.output.decode()

