    except ImportError:
        raise SystemExit("Ansible is not installed. Please install it using 'pip install ansible'.")
    ansible_args = ansible_args if ansible_args else {}
    if verbose:
        ansible_args['verbose'] = verbose
    if extra_vars:
        ansible_args['extra_vars'] = extra_vars
    ansible_args['playbook'] = playbook_path
    if isinstance(ansible_args, dict):
        ansible_args_list = []
